module sequence_in_gcd_table (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] n,\n    input wire [63:0] m,\n    input wire [3:0] k,\n    input wire [63:0] a [0:7],\n    output reg result,\n    output reg done\n);\n    // State definitions\n    localparam [3:0] IDLE       = 4'd0;\n    localparam [3:0] COMPUTE_LCM   = 4'd1;\n    localparam [3:0] SOLVE_CRT     = 4'd2;\n    localparam [3:0] CHECK_GCD     = 4'd3;\n    localparam [3:0] VERIFY_RESULT = 4'd4;\n    localparam [3:0] FINISH        = 4'd5;\n    \n    reg [3:0] state;\n    reg [63:0] lcm_val;\n    reg [63:0] crt_R;\n    reg [63:0] crt_M;\n    reg [3:0] iter_idx;\n    reg [63:0] gcd_a;\n    reg [63:0] gcd_b;\n    reg gcd_start;\n    wire [63:0] gcd_result;\n    wire gcd_done;\n    reg [63:0] j0;\n    reg [63:0] x_hold;\n    reg [63:0] y_hold;\n    reg overflow_flag;\n    reg [63:0] temp_result;\n    \n    // Internal GCD unit instantiation\n    gcd_unit gcd_inst (\n        .clk(clk),\n        .rst_n(rst_n),\n        .start(gcd_start),\n        .a(gcd_a),\n        .b(gcd_b),\n        .result(gcd_result),\n        .done(gcd_done)\n    );\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            lcm_val <= 64'd1;\n            crt_R <= 64'd0;\n            crt_M <= 64'd1;\n            iter_idx <= 4'd0;\n            gcd_a <= 64'd0;\n            gcd_b <= 64'd0;\n            gcd_start <= 1'b0;\n            j0 <= 64'd0;\n            x_hold <= 64'd0;\n            y_hold <= 64'd0;\n            overflow_flag <= 1'b0;\n            temp_result <= 64'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE_LCM;\n                        iter_idx <= 4'd0;\n                        lcm_val <= 64'd1;\n                        overflow_flag <= 1'b0;\n                    end\n                end\n                \n                COMPUTE_LCM: begin\n                    if (iter_idx < k) begin\n                        if (!gcd_start) begin\n                            gcd_a <= lcm_val;\n                            gcd_b <= a[iter_idx];\n                            gcd_start <= 1'b1;\n                        end else if (gcd_done) begin\n                            gcd_start <= 1'b0;\n                            if (gcd_result == 64'd0) begin\n                                state <= FINISH;\n                                result <= 1'b0;\n                            end else begin\n                                // Calculate LCM - check for overflow during multiplication\n                                if (lcm_val > 64'd0 && a[iter_idx] > (64'hFFFF_FFFF_FFFF_FFFF / lcm_val)) begin\n                                    overflow_flag <= 1'b1;\n                                    state <= FINISH;\n                                    result <= 1'b0;\n                                end else begin\n                                    temp_result <= (lcm_val * a[iter_idx]) / gcd_result;\n                                    lcm_val <= temp_result;\n                                    if (temp_result > n) overflow_flag <= 1'b1;\n                                    iter_idx <= iter_idx + 4'd1;\n                                end\n                            end\n                        end\n                    end else begin\n                        if (overflow_flag || lcm_val > n) begin\n                            state <= FINISH;\n                            result <= 1'b0;\n                        end else begin\n                            state <= SOLVE_CRT;\n                            iter_idx <= 4'd0;\n                            crt_R <= 64'd0;\n                            crt_M <= 64'd1;\n                        end\n                    end\n                end\n                \n                SOLVE_CRT: begin\n                    if (iter_idx < k) begin\n                        state <= SOLVE_CRT;\n                        iter_idx <= iter_idx + 4'd1;\n                    end else begin\n                        j0 <= crt_R;\n                        state <= CHECK_GCD;\n                        iter_idx <= 4'd0;\n                    end\n                end\n                \n                CHECK_GCD: begin\n                    if (iter_idx < k) begin\n                        if (!gcd_start) begin\n                            gcd_a <= lcm_val;\n                            gcd_b <= j0 + iter_idx;\n                            gcd_start <= 1'b1;\n                        end else if (gcd_done) begin\n                            gcd_start <= 1'b0;\n                            if (gcd_result != a[iter_idx]) begin\n                                state <= FINISH;\n                                result <= 1'b0;\n                            end else if (iter_idx == (k-4'd1)) begin\n                                state <= VERIFY_RESULT;\n                            end else begin\n                                iter_idx <= iter_idx + 4'd1;\n                            end\n                        end\n                    end\n                end\n                \n                VERIFY_RESULT: begin\n                    if ((j0 >= 64'd1) && (j0 + k - 64'd1 <= m)) begin\n                        result <= 1'b1;\n                    end else begin\n                        result <= 1'b0;\n                    end\n                    state <= FINISH;\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule\n\nmodule gcd_unit (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] a,\n    input wire [63:0] b,\n    output reg [63:0] result,\n    output reg done\n);\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH_STATE = 2'd2;\n    \n    reg [1:0] state;\n    reg [63:0] x;\n    reg [63:0] y;\n    reg [63:0] a_reg;\n    reg [63:0] b_reg;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 64'd0;\n            x <= 64'd0;\n            y <= 64'd0;\n            a_reg <= 64'd0;\n            b_reg <= 64'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        a_reg <= a;\n                        b_reg <= b;\n                        state <= COMPUTE;\n                        done <= 1'b0;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (b_reg == 64'd0) begin\n                        result <= a_reg;\n                        state <= FINISH_STATE;\n                    end else begin\n                        x <= a_reg;\n                        y <= b_reg;\n                        a_reg <= y;\n                        b_reg <= x % y;\n                    end\n                end\n                \n                FINISH_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule